return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n == 1 || n == 11) ? 0 : ((n == 2 || n == 12) ? 1 : ((n >= 3 && n <= 10 || n >= 13 && n <= 19) ? 2 : 3));','language'=>'gd','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:50:52+00:00','po-revision-date'=>'2026-11-05T19:50:52+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Lìonaidh e na h-eadar-theangachaidhean a tha a dhìth airson na plugain agus na cuspairean a tha stàlaichte mu thràth air an làrach agad.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Bha an sgrìn luchdaidh suas sin air a dhol à ceann-ùine: chaidh luchdadh suas eile ullachadh bhon uair sin. Cha deach dad a chur. Thoir sùil air an fhear làithreach on liosta de eadar-theangachaidhean.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Tha am plana seirbheis an-asgaidh a’ toirt àireamh chuingealaichte de shlotan do gach làrach airson plugain agus cuspairean; tha na slotan a tha ’gan cleachdadh ri fhaicinn ann an Settings às dèidh dhut Babilim a chur an comas.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Ma dh’iarras tu eadar-theangachadh, thèid am plugan no an cuspair seo a chur air aon de shlotan a’ phlana seirbheis an-asgaidh airson na làraich seo (is e %1$d a’ chrìoch airson cuspairean agus %2$d airson plugain), mura h-eil fear aige mu thràth. Aon uair ’s gun deach slot a chleachdadh, fanaidh e ’na shlot ann an cleachdadh, agus cha dèan eadar-theangachadh a dh’fhàillig slot a shaoradh.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Ma dh’iarras tu eadar-theangachadh, thèid am plugan no an cuspair seo a chur air aon de shlotan a’ phlana seirbheis an-asgaidh airson na làraich seo, mura h-eil fear aige mu thràth. Aon uair ’s gun deach slot a chleachdadh, fanaidh e ’na shlot ann an cleachdadh, agus cha dèan eadar-theangachadh a dh’fhàillig slot a shaoradh.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Mura h-eil am plugan no an cuspair seo air aon de shlotan a’ phlana seirbheis an-asgaidh airson na làraich seo fhathast, thèid a chur air fear ma dh’iarras tu eadar-theangachadh (is e %1$d a’ chrìoch airson cuspairean agus %2$d airson plugain). Aon uair ’s gun deach slot a chleachdadh, fanaidh e ’na shlot ann an cleachdadh, agus cha dèan eadar-theangachadh a dh’fhàillig slot a shaoradh. A bheil thu airson leantainn air adhart?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Mura h-eil am plugan no an cuspair seo air aon de shlotan a’ phlana seirbheis an-asgaidh airson na làraich seo fhathast, thèid a chur air fear ma dh’iarras tu eadar-theangachadh. Aon uair ’s gun deach slot a chleachdadh, fanaidh e ’na shlot ann an cleachdadh, agus cha dèan eadar-theangachadh a dh’fhàillig slot a shaoradh. A bheil thu airson leantainn air adhart?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tha %1$d làrach air an lìonra seo air a suidheachadh gus an dearbh-aithne Babilim aice a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris an làrach sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus an dearbh-aithne a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim na làraich sin, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris na làraichean sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sguabadh às nuair a thèid am plugan a sguabadh às. Chan urrainnear an cead-cleachdaidh pàighte a tha ceangailte ris na làraichean sin aiseag gu fèin-obrachail an uairsin; dh’fheumadh tu fios a chur gu taic Babilim aig %2$s. Gus na dearbh-aithnean a chumail, briog air Sguir dheth, thoir an tic far “Sguab às a h-uile dàta Babilim nuair a thèid a dhì-stàladh” ann an Roghainnean Babilim gach làraich, agus dì-ghnìomhaich a-rithist. A bheil thu airson a dhì-ghnìomhachadh co-dhiù?' . "\0" . 'Tha %1$d làrach air an lìonra seo air an suidheachadh gus an dearbh-aithne Babilim aca a sgu